        [TestCase(99999u, 3, 600, 330, 1, 1, 56, 0.7, "400,330,3.19975,-0.040006,6.4,5,400,330,0.999922,-0.012502:3:150")]
        [TestCase(99999u, 3, 299.030779, 502.641873, 1, 1, 56, 0.7, "400,330,-1.580848,2.782251,6.4,5,400,330,-0.494015,0.869453:3:150")]
        [TestCase(99999u, 3, 453.499766, 137.288363, 1, 1, 56, 0.7, "400,330,0.817381,-3.093847,6.4,5,400,330,0.255432,-0.966827:3:150")]
        public void AShotMatchesTheGame(uint seed, int weapon, double tx, double ty, int n, int jitterDraws,
                                        double cooldown, double slow, string signature)
        {
            var run = new RunState(new Rng(seed));
            run.player.x = 400; run.player.y = 330; run.player.weaponIdx = weapon; run.player.shootSlow = 0.5;
            int j0 = run.rng.JitterCalls, r0 = run.rng.RunCalls;
            Weapons.Fire(run, tx, ty);
            Assert.That(run.projectiles, Has.Count.EqualTo(n));
            Assert.That(run.rng.JitterCalls - j0, Is.EqualTo(jitterDraws), "the spread spent a different number of jitter draws");
            Assert.That(run.rng.RunCalls - r0, Is.Zero, "firing must never draw from the run stream");
            Assert.That(run.player.cooldown, Is.EqualTo(cooldown).Within(2e-6));
            Assert.That(run.player.shootSlow, Is.EqualTo(slow).Within(2e-6));
            Assert.That(run.shots, Is.EqualTo(n));
            var shells = signature.Split('|');
            for (int i = 0; i < n; i++)
            {
                var parts = shells[i].Split(':');
                var v = parts[0].Split(',');
                var q = run.projectiles[i];
                double[] got = { q.x, q.y, q.vx, q.vy, q.dmg, q.r, q.ox, q.oy, q.dx, q.dy };
                for (int k = 0; k < got.Length; k++)
                    Assert.That(got[k], Is.EqualTo(double.Parse(v[k], CultureInfo.InvariantCulture)).Within(2e-6),
                        $"shell {i}, field {k}");
                Assert.That(q.pierce, Is.EqualTo(int.Parse(parts[1], CultureInfo.InvariantCulture)));
                Assert.That(q.fNear, Is.EqualTo(double.Parse(parts[2], CultureInfo.InvariantCulture)));
            }
        }
    }
}
